 assert.match(await messages(q),/guardar|almacenamiento|guardad|cuota/i);
 await q.evaluate(()=>window.__voucherFailConfirmedWrite=false);
 if(!await q.locator('#store-item-editor[open]').count())await prepareOffer(q);
 await q.locator('#store-item-save').click();await editor(q).waitFor({state:'hidden'});
 const quotaId=(await record(q)).state.observed.shop.value.voucherOffers[0].offerId;
 assert.equal((await record(q)).state.observed.shop.value.voucherOffers.length,1);
 before=await raw(q);await openVoucher(q,quotaId);
 await q.locator('#store-item-price').fill('7');await q.evaluate(()=>window.__voucherFailConfirmedWrite=true);
 await q.locator('#store-item-save').click();assert.equal(await raw(q),before);
 assert.equal((await cache(q)).vouchers[0].price,10);
 assert.match(await tile(q,quotaId).innerText(),/\$10/);
 await q.evaluate(()=>window.__voucherFailConfirmedWrite=false);await closeEditor(q);
 await begin(q,quotaId);await q.locator('#performed').check();
 await q.evaluate(()=>window.__voucherFailConfirmedWrite=true);await q.locator('#dialog-accept').click();
 assert.equal(await raw(q),before);saved=await record(q);
 assert.equal(saved.state.observed.money.value,40);
 assert.equal(saved.state.observed.resources.handsPerRound.value,5);
 assert.deepEqual(saved.state.observed.outOfScope.value.vouchers,[]);
 assert.equal(saved.state.observed.shop.value.voucherOffers.length,1);
 assert.equal((await cache(q)).vouchers[0].offerId,quotaId);
 assert.equal(await q.locator('#confirmation[open]').count(),1);
 assert.match(await messages(q),/guardar|almacenamiento|guardad|cuota/i);
 await q.evaluate(()=>window.__voucherFailConfirmedWrite=false);
 await q.locator('#dialog-accept').click();await q.locator('#confirmation').waitFor({state:'hidden'});
 saved=await record(q);assertBasePurchase(saved,quotaId);
 assert.equal(saved.history.filter(entry=>entry.action?.type==='buy_voucher').length,1);
 before=await raw(q);await reload(q);assert.equal(await raw(q),before);
